ALTER TABLE el_attendance ADD COLUMN revision INTEGER NOT NULL DEFAULT 0;
CREATE TABLE el_attendance_corrections(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,attendance_id TEXT NOT NULL,base_revision INTEGER NOT NULL,old_status TEXT NOT NULL,new_status TEXT NOT NULL CHECK(new_status IN ('present','absent','late','excused','left_early')),arrival INTEGER,departure INTEGER,notes TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL,requested_by TEXT NOT NULL,reviewed_by TEXT,decision_note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at INTEGER NOT NULL,reviewed_at INTEGER,CHECK(departure IS NULL OR arrival IS NULL OR departure>=arrival),CHECK(reviewed_by IS NULL OR reviewed_by<>requested_by),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,requested_by) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,reviewed_by) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(attendance_id) REFERENCES el_attendance(id));
CREATE UNIQUE INDEX el_attendance_correction_pending ON el_attendance_corrections(attendance_id) WHERE status='pending';
CREATE INDEX el_attendance_corrections_queue ON el_attendance_corrections(org_id,branch_id,status,created_at);
CREATE TRIGGER el_attendance_correction_final BEFORE UPDATE ON el_attendance_corrections WHEN OLD.status<>'pending' BEGIN SELECT RAISE(ABORT,'Attendance correction is finalized'); END;
CREATE TRIGGER el_attendance_correction_identity BEFORE UPDATE ON el_attendance_corrections WHEN NEW.id<>OLD.id OR NEW.org_id<>OLD.org_id OR NEW.branch_id<>OLD.branch_id OR NEW.attendance_id<>OLD.attendance_id OR NEW.base_revision<>OLD.base_revision OR NEW.old_status<>OLD.old_status OR NEW.new_status<>OLD.new_status OR NEW.arrival IS NOT OLD.arrival OR NEW.departure IS NOT OLD.departure OR NEW.notes<>OLD.notes OR NEW.reason<>OLD.reason OR NEW.requested_by<>OLD.requested_by BEGIN SELECT RAISE(ABORT,'Attendance correction request is immutable'); END;
CREATE TRIGGER el_attendance_correction_decision BEFORE UPDATE OF status ON el_attendance_corrections WHEN NEW.status<>'pending' BEGIN
 SELECT CASE WHEN NEW.reviewed_by IS NULL OR NEW.reviewed_by=NEW.requested_by OR NEW.reviewed_at IS NULL THEN RAISE(ABORT,'Attendance correction needs independent review') END;
 SELECT CASE WHEN NEW.status='approved' AND NOT EXISTS(SELECT 1 FROM el_attendance a JOIN el_class_sessions s ON s.id=a.session_id WHERE a.id=NEW.attendance_id AND a.org_id=NEW.org_id AND s.branch_id=NEW.branch_id AND s.status<>'cancelled' AND a.revision=NEW.base_revision) THEN RAISE(ABORT,'Attendance correction is stale') END;
END;
CREATE TRIGGER el_attendance_correction_apply AFTER UPDATE OF status ON el_attendance_corrections WHEN NEW.status='approved' BEGIN
 UPDATE el_attendance SET status=NEW.new_status,arrival=NEW.arrival,departure=NEW.departure,notes=NEW.notes,recorded_by=NEW.reviewed_by,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=NEW.attendance_id AND org_id=NEW.org_id;
 DELETE FROM el_academic_alerts WHERE session_id=(SELECT session_id FROM el_attendance WHERE id=NEW.attendance_id) AND student_id=(SELECT student_id FROM el_attendance WHERE id=NEW.attendance_id) AND kind='absence' AND NEW.new_status<>'absent';
 INSERT INTO el_academic_alerts(id,org_id,branch_id,student_id,session_id,kind,message,is_demo) SELECT NEW.id,a.org_id,NEW.branch_id,a.student_id,a.session_id,'absence','Attendance corrected to absent. In-app guardian alert.',a.is_demo FROM el_attendance a WHERE a.id=NEW.attendance_id AND NEW.new_status='absent' ON CONFLICT(session_id,student_id,kind) DO UPDATE SET message=excluded.message;
END;
CREATE TRIGGER el_attendance_change_approval BEFORE UPDATE ON el_attendance WHEN NEW.status<>OLD.status OR NEW.arrival IS NOT OLD.arrival OR NEW.departure IS NOT OLD.departure OR NEW.notes<>OLD.notes BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_attendance_corrections r WHERE r.attendance_id=OLD.id AND r.org_id=OLD.org_id AND r.base_revision=OLD.revision AND r.status='approved' AND r.new_status=NEW.status AND r.arrival IS NEW.arrival AND r.departure IS NEW.departure AND r.notes=NEW.notes AND r.reviewed_by=NEW.recorded_by AND NEW.revision=OLD.revision+1) THEN RAISE(ABORT,'Attendance correction approval required') END;
END;
